  function historyPayload(){
    const d=formData(), valid=lastCalculations.filter(c=>!c.empty&&!c.pending);
    const items=lastCalculations.filter(c=>!c.empty).map(c=>({material:c.p?.name||'Material pending',quantity:c.line.qty,unit:c.p?.unit||'',type:c.line.type,pricePerUnit:Number.isFinite(+c.finalUnit)?+c.finalUnit:null,loads:c.loads??null,total:c.pending?null:c.extended}));
    const payload={rfp:d.rfp,customer:d.customer,attention:d.attention,phone:d.phone,email:d.email,billing:d.billing,project:d.project,deliveryAddress:d.deliveryAddress,generalContractor:d.generalContractor,owner:d.owner,terms:d.terms,total:valid.reduce((n,c)=>n+c.extended,0),tax:valid.reduce((n,c)=>n+c.taxInUnit*(+c.line.qty),0),items,rfpHtml:$('#rfpPaper').innerHTML};
    const source=JSON.stringify({form:d,lines:lines.map(({id,...line})=>line),items,total:payload.total,rfpHtml:payload.rfpHtml});
    let hash=2166136261;for(let i=0;i<source.length;i++){hash^=source.charCodeAt(i);hash=Math.imul(hash,16777619)}
    payload.quoteKey=(hash>>>0).toString(36);return payload;
  }
  function saveHistoryEvent(action){
    const entries=quoteHistory(), payload=historyPayload(), now=new Date().toISOString();
    let record=entries.find(q=>q.quoteKey===payload.quoteKey);
    if(!record){record={...payload,id:`q-${Date.now()}-${Math.random().toString(36).slice(2,8)}`,createdAt:now,status:'Pending to send',notes:'',events:[]};entries.unshift(record)}
    else Object.assign(record,payload);
    record.events=Array.isArray(record.events)?record.events:[];record.events.push({action,at:now});
    if(action==='sent'){record.status='Sent · pending approval';record.sentAt=now}
    if(action==='outlook')record.outlookOpenedAt=now;
    if(action==='pdf')record.pdfSavedAt=now;
    record.updatedAt=now;
    return saveQuoteHistory(entries)?record:null;
  }
  function approvalCounts(entries){
    const approved=entries.filter(q=>q.status==='Approved by customer').length;
    const rejected=entries.filter(q=>q.status==='Rejected by customer').length;
    const pending=entries.filter(q=>['Sent','Sent · pending approval'].includes(q.status)).length;
    const unsent=entries.filter(q=>!['Sent','Sent · pending approval','Approved by customer','Rejected by customer'].includes(q.status)).length;
    const sent=approved+rejected+pending;
    return {approved,rejected,pending,unsent,sent,approvedPct:sent?approved/sent*100:0,rejectedPct:sent?rejected/sent*100:0,pendingPct:sent?pending/sent*100:0};
  }
  function renderHistorySummary(entries){
    const x=approvalCounts(entries), max=Math.max(1,x.approved,x.rejected,x.pending,x.unsent);
    const row=(label,n,cls,pct)=>`<div class="chart-row"><span>${label}</span><div class="chart-track"><div class="chart-fill ${cls}" style="width:${Math.max(n?2:0,n/max*100)}%"></div></div><b>${n} · ${pct.toFixed(1)}%</b></div>`;
    $('#historySummary').innerHTML=`<div class="history-summary"><div class="history-kpis"><div class="history-kpi"><span>Total quotes</span><strong>${entries.length}</strong></div><div class="history-kpi"><span>Approved</span><strong>${x.approvedPct.toFixed(1)}%</strong></div><div class="history-kpi"><span>Rejected</span><strong>${x.rejectedPct.toFixed(1)}%</strong></div><div class="history-kpi"><span>Pending</span><strong>${x.pending}</strong></div></div><div class="history-chart"><h3>Quote outcomes</h3>${row('Approved',x.approved,'chart-approved',x.approvedPct)}${row('Rejected',x.rejected,'chart-rejected',x.rejectedPct)}${row('Pending approval',x.pending,'chart-pending',x.pendingPct)}${row('PDF not sent',x.unsent,'chart-unsent',entries.length?x.unsent/entries.length*100:0)}</div></div>`;
  }
  function renderHistory(){
    const host=$('#historyList'),entries=quoteHistory().sort((a,b)=>new Date(b.updatedAt||b.sentAt||b.createdAt||0)-new Date(a.updatedAt||a.sentAt||a.createdAt||0));
    renderHistorySummary(entries);
    if(!entries.length){host.innerHTML='<div class="history-empty">No quotes in the history yet. Downloading a PDF or registering a send will add it automatically.</div>';return}
    host.innerHTML=entries.map(q=>{
      const when=q.sentAt||q.pdfSavedAt||q.outlookOpenedAt||q.createdAt;
      const stamp=new Date(when||0), date=Number.isNaN(stamp.getTime())?'Unknown date':new Intl.DateTimeFormat('en-US',{dateStyle:'medium',timeStyle:'short'}).format(stamp);
      const status=q.status==='Enviada'?'Sent · pending approval':HISTORY_STATUSES.includes(q.status)?q.status:'Pending to send';
      const items=(q.items||[]).map(x=>`<li>${esc(x.material)} · ${number(x.quantity,2)} ${esc(x.unit)} · ${esc(x.type||'')} · ${x.loads??'—'} loads · ${x.pricePerUnit==null?'Price pending':`${money(x.pricePerUnit)}/${esc(x.unit)}`} · ${x.total==null?'Amount pending':money(x.total)}</li>`).join('');
      const sentAction=status==='Pending to send'?'<button class="btn" data-history-send="'+esc(q.id)+'">Confirm send</button>':'';
      const pdfAction=q.rfpHtml?'<button class="btn" data-history-pdf="'+esc(q.id)+'">Open / save PDF</button>':'';
      return `<article class="history-entry"><div class="history-entry-head"><div><div class="history-entry-title">${esc(q.customer||'Unnamed customer')} · ${esc(q.project||'Unnamed project')}</div><div class="history-entry-meta">RFP: ${esc(q.rfp||'—')} · Activity: ${esc(date)} · Total: ${money(q.total||0)}</div></div><label class="history-fields history-status">Status<select data-history-status="${esc(q.id)}">${HISTORY_STATUSES.map(x=>`<option ${x===status?'selected':''}>${esc(x)}</option>`).join('')}</select></label></div><details class="history-details"><summary>View lines and customer data</summary><ul>${items||'<li>No lines recorded</li>'}</ul><div>Contact: ${esc(q.attention||'—')} · ${esc(q.phone||'—')} · ${esc(q.email||'—')}</div><div>Delivery address: ${esc(q.deliveryAddress||'—')}</div></details><div class="history-fields"><label>Notes to support the status<textarea maxlength="2000" data-history-notes="${esc(q.id)}" placeholder="E.g. follow-up date, approval reason or rejection reason">${esc(q.notes||'')}</textarea><span class="history-save-note">Notes are saved automatically in this browser.</span></label><div class="history-actions">${pdfAction}${sentAction}</div></div></article>`;
    }).join('');
  }
  function printStoredQuote(id){
    const q=quoteHistory().find(x=>x.id===id);if(!q?.rfpHtml){alert('There is no saved proposal for this quote.');return}
    const popup=window.open('about:blank','_blank');if(!popup){alert('The browser blocked the window. Allow pop-ups to open the PDF.');return}
    const css=[...document.querySelectorAll('style')].map(s=>s.textContent).join('\n');
    popup.document.open();popup.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>RFP ${esc(q.rfp||q.project||'JCK')}</title><style>${css}.pdf-actions{max-width:980px;margin:12px auto;display:flex;justify-content:flex-end;gap:8px}.pdf-actions button{padding:9px 13px;border:1px solid #d1dbe5;border-radius:8px;background:#306aa1;color:white;font-weight:bold}@media print{.pdf-actions{display:none!important}}</style></head><body><div class="pdf-actions"><button onclick="window.print()">Print / Save PDF</button></div><article class="rfp-paper">${q.rfpHtml}</article></body></html>`);popup.document.close();
  }

