  function quoteHasOpenFlags(){
    const open=lastCalculations.filter(c=>!c.empty&&(c.pending||c.flags.some(f=>f.type==='error'||f.text.includes('CONFIRM'))));
    if(open.length){alert('Resolve the red or pending alerts first before downloading the PDF or registering the send.');return false}return true;
  }
  function registerQuoteAsSent(){
    if(!$('#rfpScreen').classList.contains('open')||!lastCalculations.some(c=>!c.empty)){alert('Review a complete RFP proposal first.');return}
    if(!quoteHasOpenFlags())return;
    if(!confirm('Confirm that you already sent this RFP to the customer.'))return;
    if(!saveHistoryEvent('sent'))return;
    $('#registerSentBtn').textContent='Sent ✓';$('#registerSentBtn').disabled=true;alert('Quote registered as sent in the browser history.');
  }
  // Downloads the RFP proposal as a PDF file (PDF only, no print dialog).
  async function downloadPdf(){
    if(!$('#rfpScreen').classList.contains('open')||!lastCalculations.some(c=>!c.empty)){alert('Review a complete RFP proposal first.');return}
    if(!quoteHasOpenFlags())return;
    const el=$('#rfpPaper');if(!el||!el.innerHTML.trim()){alert('Review a complete RFP proposal first.');return}
    if(!window.html2pdf){alert('Could not load the PDF generator.');return}
    const btn=$('#downloadPdfBtn'),prev=btn.textContent;btn.disabled=true;btn.textContent='Generating PDF…';
    // Clone the proposal and normalize it: drop the min-height, the centering margin
    // and the shadow so there is no blank band, and fix a letter-width.
    const W=740; // letter content width (px) with 10mm margins
    const clone=el.cloneNode(true);
    clone.style.minHeight='0';clone.style.maxWidth='none';clone.style.margin='0';clone.style.boxShadow='none';clone.style.width=W+'px';clone.style.background='#fff';
    // Render in the document flow (top-left), not off-screen with position:fixed,
    // so html2canvas does not offset the capture origin.
    const wrap=document.createElement('div');wrap.style.cssText='position:absolute;left:0;top:0;width:'+W+'px;background:#fff;z-index:-9999;';wrap.appendChild(clone);document.body.appendChild(wrap);
    const prevScroll=window.scrollY||window.pageYOffset||0;window.scrollTo(0,0);
    const d=formData(),base=(d.rfp||d.project||'Quote').replace(/[^A-Za-z0-9_\-]+/g,'_').slice(0,60)||'Quote';
    try{
      await window.html2pdf().set({
        margin:[10,10,12,10],
        filename:`JCK_${base}.pdf`,
        image:{type:'jpeg',quality:0.95},
        html2canvas:{scale:2,useCORS:true,backgroundColor:'#ffffff',scrollX:0,scrollY:0,x:0,y:0,windowWidth:W},
        jsPDF:{unit:'mm',format:'letter',orientation:'portrait'},
        // Keep table rows, headers and images from splitting across pages.
        pagebreak:{mode:['css','legacy'],avoid:['tr','thead','tfoot','img']}
      }).from(clone).save();
      saveHistoryEvent('pdf');
    }catch(err){alert('Could not generate the PDF.');}
    finally{wrap.remove();window.scrollTo(0,prevScroll);btn.disabled=false;btn.textContent=prev;}
  }

  function saveHistoryEdit(id,key,value){const entries=quoteHistory();const q=entries.find(x=>x.id===id);if(!q)return;q[key]=value;if(key==='status'&&['Sent','Sent · pending approval'].includes(value)&&!q.sentAt)q.sentAt=new Date().toISOString();q.updatedAt=new Date().toISOString();if(saveQuoteHistory(entries))renderHistory()}
  function buildRfp(){if(!formData().customer||!formData().project){alert('Enter the customer legal name and the project name.');return}const c=lastCalculations.filter(x=>!x.empty);if(!c.length){alert('Add at least one line with a quantity.');return}const d=formData();$('#registerSentBtn').disabled=false;$('#registerSentBtn').textContent='Register as sent';const now=new Date();const date=new Intl.DateTimeFormat('en-US',{month:'2-digit',day:'2-digit',year:'numeric'}).format(now);const expires=new Date(now);expires.setDate(expires.getDate()+config.settings.validDays);const hold=new Date(now);hold.setMonth(hold.getMonth()+config.settings.holdMonths);const fmt=x=>new Intl.DateTimeFormat('en-US').format(x);const terms=config.terms.find(x=>x.name===d.terms);const valid=c.filter(x=>!x.pending);const total=valid.reduce((n,x)=>n+x.extended,0);const tax=valid.reduce((n,x)=>n+x.taxInUnit*(+x.line.qty),0);const rows=c.map((x,i)=>{const p=x.p;return `<tr><td>${i+1}</td><td>${esc(p.id)}</td><td>${esc(p.name)}</td><td>${esc(p.spec||p.note||'')}</td><td>${x.line.type.includes('Origin')?'FOB Origin':x.line.type.includes('Destination')?'FOB Destination':'Transport'}</td><td>${number(x.line.qty,2)} ${esc(p.unit)}</td><td>${x.loads??'—'}</td><td>${money(x.finalUnit)}</td><td>${x.pricePerLoad?money(x.pricePerLoad):'—'}</td><td>${money(x.extended)}</td></tr>`}).join('');const pending=c.some(x=>x.pending||x.flags.some(f=>f.type==='error'||f.text.includes('CONFIRM')));$('#rfpPaper').innerHTML=`<div class="rfp-top"><div class="rfp-logo">JCK<span> Sand Pit</span></div><div class="rfp-company"><b>${esc(config.settings.company)}</b><br>${esc(config.settings.address)}<br>Phone: ${esc(config.settings.phone)}<br>Email: ${esc(config.settings.email)}</div></div><div class="rfp-title">PROPOSAL AND PURCHASE AGREEMENT ${pending?'<span style="float:right;color:#ffb7a9;font-size:10px">DRAFT · OPEN ITEMS</span>':''}</div><div class="rfp-two"><div><h3>CUSTOMER</h3>${detail('RFP #',d.rfp)}${detail('Customer',d.customer)}${detail('Billing address',d.billing)}${detail('Attn / title',d.attention)}${detail('Phone',d.phone)}${detail('Email',d.email)}${detail('Payment terms',d.terms)}</div><div><h3>PROJECT</h3>${detail('Date',date)}${detail('Proposal expires',fmt(expires))}${detail('Price held through',fmt(hold))}${detail('Project name',d.project)}${detail('Delivery address',d.deliveryAddress)}${detail('General contractor',d.generalContractor)}${detail('Project owner',d.owner)}${detail('Start / duration',d.startDate?`${d.startDate} · ${d.duration||'TBD'} business days`:'TBD')}</div></div><p class="rfp-copy">JCK Sand Pit LLC will supply the materials and transportation services listed below. FOB basis is stated on each line: FOB Origin = customer picks up at ${esc(config.settings.address)}, and risk of loss passes at loading; FOB Destination = JCK delivers to the project address, and risk of loss passes at delivery. Quantities are estimates; invoices follow actual scale or truck tickets.</p><table class="rfp-table"><thead><tr><th>Item</th><th>Mat #</th><th>Material</th><th>Description / Spec</th><th>FOB</th><th>Qty</th><th>Est. Loads</th><th>Price / Unit</th><th>Price / Load</th><th>Total</th></tr></thead><tbody>${rows}</tbody></table><table class="rfp-totals"><tr><td>Materials and transport (incl. tax)</td><td>${money(total)}</td></tr><tr><td>Tax included (estimated) · configured rate ${(config.settings.taxRate*100).toFixed(2)}%</td><td>${money(tax)}</td></tr><tr class="total"><td>TOTAL ESTIMATE</td><td>${money(total)}</td></tr></table><div class="rfp-note">Prices include Texas sales tax where applicable. Freight includes fuel. Confirm tax treatment and supplier pricing before acceptance. This proposal is subject to final JCK review.</div><div class="rfp-terms"><h3>PAYMENT TERMS</h3><p>${terms?.wording||'Payment terms are as shown in the customer section of this proposal.'}</p><p><b>Credit.</b> Terms apply only after an approved credit application, before the first load. Returned check fee: $100. Customer pays reasonable costs of collection, including attorney fees.</p><h3>COMMERCIAL TERMS</h3><p><b>Invoicing.</b> Materials are invoiced weekly, supported by source scale or truck tickets.</p><p><b>Price hold.</b> Unit prices are firm through the 'Price held through' date and are specific to this project.</p><p><b>Escalation.</b> Outside the hold period, price changes are given 30 days' written notice. Where the hold exceeds supplier price protection, prices are subject to a published-index escalator.</p><p><b>Fuel.</b> Freight prices include fuel at the EIA Gulf Coast (PADD 3) on-highway diesel 4-week average of $5.871/gal on the proposal date. If that average moves more than $0.50/gal during the price hold, freight prices adjust in proportion to the change in fuel cost, with written notice.</p><p><b>Heavy haul.</b> Billed yard to yard in 15-minute increments after the configuration minimum, including loading, securement, unloading and customer-caused waiting. Permits at state fee plus $75 each; third-party services at cost plus 15%; tolls at cost. Cancellation within 24 hours of dispatch: $350; after dispatch, the minimum or time accrued, whichever is greater. Customer provides accurate dimensions and weight; changes on site are repriced.</p><p><b>Quantities.</b> Unit prices apply to actual quantities delivered, measured at the source scale or by truck ticket. Quantities shown are estimates, not a guaranteed minimum or maximum.</p><p><b>Measurement basis.</b> Cubic-yard items are truck-measured at the source using the conversion factors in this proposal. In-place compacted measure is not accepted unless separately priced.</p><p><b>Taxes.</b> Prices include Texas sales and use tax where the item is taxable, at the rate in effect on the date of execution; tax included per unit is shown on each line. Delivery charges are taxable only with taxable materials. A Customer claiming a resale or exemption certificate must provide it before the first load; prices are then reduced by the tax shown.</p><p><b>Changes.</b> All changes to an executed proposal must be agreed in writing by both parties.</p><h3>ACCEPTANCE</h3><p>AGREED: The undersigned accepts the prices, specifications and conditions above, including the Terms and Conditions that follow, and authorizes JCK Sand Pit LLC to supply the materials and services as specified. This proposal is not valid until signed by both parties.</p><h3>TERMS AND CONDITIONS</h3><p><b>Definitions.</b> 'Vendor' means JCK Sand Pit LLC. 'Customer' means the party purchasing goods under this proposal. 'Project' means the work identified on the face of the proposal. Where the Customer has entered a subcontract for the Project, that subcontract is the 'Prime Subcontract' and the contract between the prime contractor and the owner is the 'Prime Contract'.</p><p><b>Material quality.</b><br>1. Customer is responsible for determining whether the material meets the specifications of its Project, and may test the material as often as it sees fit, at its expense.<br>2. If material does not meet specification, Customer shall notify Vendor immediately and before placement, so that Vendor has the opportunity to cure.<br>3. Vendor assumes no liability for material placed, compacted, or incorporated into the work without first affording Vendor the opportunity to inspect and cure.<br>4. On FOB Origin orders, Customer is responsible for payment for all material loaded and transported out of the Vendor's premises, whether or not Customer subsequently rejects it.</p><p><b>Payment and credit.</b><br>1. Customer shall pay in full, without deduction or setoff, on the due date of each billing.<br>2. Accounts past due are delinquent and credit privileges are subject to review.<br>3. Vendor may revise or revoke credit arrangements if Customer fails to abide by the invoice or credit terms, or if Vendor determines in good faith that Customer will be unable to pay amounts due.<br>4. Customer is responsible for late fees and collection costs, including reasonable attorneys' fees, arising from its untimely payment.<br>5. A $100 fee applies to any check returned for insufficient funds.</p><p><b>Credit evaluation.</b> Any credit limit and terms extended are subject to review and approval based on Vendor's credit evaluation. Customer acknowledges that Vendor may obtain and review business credit information, including commercial credit agency reports, to determine eligibility, set credit limits, and modify terms. Vendor reserves the right to adjust, condition, or withdraw credit terms at any time based on that information or on changes in Customer's credit profile.</p><p><b>Delivery and title.</b><br>1. On FOB Origin orders, all transportation and insurance charges are paid by Customer, and Customer assumes risk of loss from the time the material is loaded.<br>2. On FOB Destination orders, risk of loss passes to Customer upon delivery to the site. Vendor retains a purchase-money security interest in the goods until paid in full.<br>3. Delivery dates are estimates. Vendor will use commercially reasonable efforts to meet the delivery schedule and, if behind schedule, will apply additional resources within reason at its own expense.</p><p><b>Inspection and rejection.</b> Customer shall inspect each shipment and may accept or reject it within 24 hours of delivery. Material not rejected within that period is accepted. Rejected material agreed by both parties to be non-conforming will, at Vendor's option, be replaced or credited, and removed at Vendor's expense.</p><p><b>Force majeure.</b> Vendor is not liable for failure or delay in delivery caused by act of God, fire, flood, drought, war, pandemic, epidemic, labor disruption, supplier failure, or any other cause beyond its reasonable control. At Vendor's option the delivery period is extended by the period of delay, or the order is reduced by the quantity omitted.</p><p><b>Insurance.</b> If Customer or its employees or agents enter a Vendor facility, jobsite, or Project in connection with the sale of goods, Customer shall provide and maintain, at minimum: Workers' Compensation in conformity with the law of the state where the sale is performed; Commercial General Liability of $1,000,000 each occurrence, $2,000,000 products/completed operations aggregate, $1,000,000 personal and advertising injury; and Comprehensive Automobile Liability of $1,000,000 combined single limit. Where Customer carries higher limits, Vendor and other additional insureds have access to the full limits available. These provisions are intended to comply with Chapter 151 of the Texas Insurance Code and are to be read as broadly as that chapter permits.</p><p><b>Indemnity.</b> TO THE FULLEST EXTENT PERMITTED BY APPLICABLE LAW, CUSTOMER SHALL INDEMNIFY, DEFEND, AND HOLD HARMLESS VENDOR AND ITS AFFILIATES, PARTNERS, OFFICERS, DIRECTORS, AGENTS, AND EMPLOYEES FROM AND AGAINST ALL CLAIMS, DAMAGES, LOSSES, AND EXPENSES, INCLUDING REASONABLE ATTORNEYS' FEES, TO THE EXTENT ARISING OUT OF OR RELATING TO CUSTOMER'S PERFORMANCE UNDER THIS AGREEMENT OR THE ACTS OR OMISSIONS OF CUSTOMER'S EMPLOYEES, AGENTS, SUBCONTRACTORS, OR SUPPLIERS. Customer's assumption of liability is independent of, and not limited by, its insurance coverage or lack of coverage, or by any limit on benefits payable under workers' compensation or disability acts. Nothing herein requires Customer to indemnify Vendor for a claim caused by Vendor's own negligence except as permitted under Chapter 151 of the Texas Insurance Code. This provision survives termination and is to be read as broadly as Chapter 151 permits.</p><p><b>Prime contract flow-down.</b> Where the face of the proposal identifies a Prime Contract or Prime Subcontract, the Contract Documents consist of this proposal, these Terms and Conditions, and any exhibits, together with the drawings and specifications issued before execution and any written change orders issued after. Vendor's obligations are limited to the supply of the goods and services described on the face of the proposal. Vendor does not assume Customer's performance obligations under the Prime Subcontract.</p><p><b>Governing law.</b> This Agreement is governed by the laws of the State of Texas, without regard to conflict of laws principles. Venue for any dispute lies in the county where the Vendor's facility identified on the face of the proposal is located.</p><p><b>Entire agreement.</b> This proposal and these Terms and Conditions are the entire agreement between the parties as to its subject matter. Additional or different terms proposed by Customer, including those in any purchase order or acknowledgment, are rejected unless expressly accepted in writing by Vendor.</p></div><div class="rfp-sign"><div><b>VENDOR: ${esc(config.settings.company)}</b><div class="sigline">Authorized signature / date</div></div><div><b>CUSTOMER</b><div class="sigline">Authorized signature / date</div></div></div>`;function detail(label,value){return `<div class="rfp-detail"><b>${label}</b><span>${esc(value||'—')}</span></div>`}$('#rfpScreen').classList.add('open')}
